def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = max(set(v for row in grid for v in row),
             key=lambda v: sum(row.count(v) for row in grid))
    ones = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    sixes = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]

    for i, (r1, c1) in enumerate(ones):
        for r2, c2 in ones[i + 1:]:
            dr, dc = r2 - r1, c2 - c1
            if abs(dr) != abs(dc) or dr == 0:
                continue

            sr = 1 if dr > 0 else -1
            sc = 1 if dc > 0 else -1
            segment = []
            r, c = r1, c1
            while True:
                segment.append((r, c))
                if (r, c) == (r2, c2):
                    break
                r += sr
                c += sc

            for r, c in segment:
                if out[r][c] == bg:
                    out[r][c] = 1

            for ar, ac in sixes:
                if (ar, ac) not in segment:
                    continue
                # Extend the 6 diagonally, perpendicular to the 1 segment.
                r, c = ar, ac
                while 0 <= r - sr < h and 0 <= c + sc < w:
                    r -= sr
                    c += sc
                while 0 <= r < h and 0 <= c < w:
                    if out[r][c] == bg:
                        out[r][c] = 6
                    r += sr
                    c -= sc

    return out
